function total(values) {
  if (!Array.isArray(values)) throw new TypeError('Input must be an array');
  let sum = 0;
  for (const value of values) {
    if (typeof value !== 'number' || !isFinite(value)) {
      throw new TypeError('All elements must be finite numbers');
    }
    sum += value;
  }
  return sum;
}
export { total };

import { total } from './total.js';

test('sums finite numbers', () => {
  expect(total([2, 3])).toBe(5);
  expect(total([-2, -3])).toBe(-5);
  expect(total([])).toBe(0);
});

test('rejects nonnumeric entries', () => {
  expect(() => total(['invalid'])).toThrow();
  expect(() => total([NaN])).toThrow();
  expect(() => total([Infinity])).toThrow();
});
